static void unstuff_msg(const uint8_t *w, int n, const uint8_t *want, int wn, const char *what){
    zd1_unstuff_t u = {0}; uint8_t got[300]; int k = 0, i; uint8_t b;
    for(i = 0; i < n; i++) if(zd1_unstuff(&u, w[i], &b) == ZD1_RX_BYTE && k < 300) got[k++] = b;
    CHECK(k == wn && !memcmp(got, want, wn), "unstuff %s", what);
}
