static void play_icons(void){
    { zd1_play_matcher_t m = {0}; const char x[] = "<update id=\"status\"><icon id=\"play\">pl</icon></update>"; int r = ZD1_PLAY_NONE, i; for(i = 0; x[i]; i++){ int v = zd1_play_push(&m, x[i]); if(v) r = v; } CHECK(r == ZD1_PLAY_PLAYING, "play %s", x); }
    { zd1_play_matcher_t m = {0}; const char x[] = "<update id=\"status\"><icon id=\"play\">pa</icon></update>"; int r = ZD1_PLAY_NONE, i; for(i = 0; x[i]; i++){ int v = zd1_play_push(&m, x[i]); if(v) r = v; } CHECK(r == ZD1_PLAY_PAUSED, "play %s", x); }
    { zd1_play_matcher_t m = {0}; const char x[] = "<update id=\"status\"><icon id=\"play\">em</icon></update>"; int r = ZD1_PLAY_NONE, i; for(i = 0; x[i]; i++){ int v = zd1_play_push(&m, x[i]); if(v) r = v; } CHECK(r == ZD1_PLAY_EMPTY, "play %s", x); }
}

int main(void){
    stuffing(); messages(); volumes(); kinds_and_codes(); play_icons();
    printf(fails ? "zd1link_gen: %d FAILED\n" : "zd1link_gen: all ok\n", fails);
    return fails != 0;
}
